import './App.css';

import minecraftItems from 'minecraft-items';
import items121 from './items121.json';
import { Slot } from './slot';
import React, { Component } from 'react';

const DEFAULT_ICON = 'iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAQAAADZc7J/AAAAF0lEQVRIDWMYBaNgFIyCUTAKRsEoQAMACCAAATXQUGAAAAAASUVORK5CYII=';

// Merge items and ensure uniqueness by name
const oldItems = [...minecraftItems.find('')];
const existingNames = new Set(oldItems.map(i => (i.name || '').toLowerCase()));
const newItems = [];

items121.forEach(item => {
  const name = item.displayName;
  if (name && !existingNames.has(name.toLowerCase())) {
    newItems.push({
      name: name,
      nameId: item.name || '', // e.g. 'axolotl_bucket'
      icon: DEFAULT_ICON,
      id: item.id
    });
  }
});

// Put new items at the front for visibility
const allItems = [...newItems, ...oldItems];

export const allItemsList = allItems;

export const findItems = (query) => {
  if (!query) return allItems;
  const lowerQuery = query.toLowerCase();
  // Also search with underscores replaced by spaces (e.g. 'axolotl_bucket' -> 'axolotl bucket')
  const altQuery = lowerQuery.replace(/_/g, ' ');
  return allItems.filter(item => {
    const name = (item.name || '').toLowerCase();
    const nameId = (item.nameId || '').toLowerCase();
    return name.includes(lowerQuery) || name.includes(altQuery) ||
      nameId.includes(lowerQuery) || nameId.includes(altQuery);
  });
}

export class Search extends Component {
  state = {
    items: []
  }
  componentDidMount() {
    this.setState({
      items: findItems('').slice(0, 54)
    });
  }
  handleChange = (e) => {
    let search = findItems(e.target.value).slice(0, 53);

    let empty = new Array(54 - search.length).fill({ empty: true })
    let items = [...search, ...empty];
    this.setState({
      items,
    });
  }
  render() {
    return (
      <div>
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            marginBottom: '2px'
          }}
        >
          <span>{this.props.title}</span>
          <input
            type="text"
            name="search"
            onChange={this.handleChange}
          />
        </div>
        <div
          id="itemsSearch"
          style={{
            justifyContent: 'center',
          }}
        >
          {this.state.items.map((itm, index) => (
            <div key={itm.id != null ? itm.id + '_s' : 'empty_' + index} onClick={() => { if (!itm.empty) this.props.selectedFromSearch(itm) }}>
              <Slot
                selectedSlot={this.props.selectedFromSearch}
                icon={itm.icon}
                isSearch={true}
              />
            </div>
          ))}
        </div>
      </div>
    )
  }

}
